package kr.or.arte.seal.delivery.application;
import com.fasterxml.jackson.databind.*;import org.springframework.stereotype.Component;import org.springframework.web.util.HtmlUtils;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.HexFormat;
@Component public class ConsentMailRenderer{
 private final ObjectMapper json;public ConsentMailRenderer(ObjectMapper json){this.json=json;}
 public RenderedConsentMail render(String snapshot,String recipientName,String publicUrl){try{JsonNode n=json.readTree(snapshot);String title=text(n,"title");StringBuilder items=new StringBuilder();for(JsonNode item:n.path("items")){items.append("<section style=\"border:1px solid #d9e2ef;border-radius:10px;padding:16px;margin:12px 0\"><strong>").append(escape(text(item,"title"))).append("</strong><p>처리 목적: ").append(escape(text(item,"purpose"))).append("</p><p>보유기간: ").append(escape(text(item,"retentionText"))).append("</p><p>").append(escape(text(item,"refusalNotice"))).append("</p></section>");}
  String html="<!doctype html><html lang=\"ko\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>"+escape(title)+"</title></head><body style=\"margin:0;background:#eef3f9;font-family:Arial,'Malgun Gothic',sans-serif;color:#172033\"><main style=\"max-width:680px;margin:auto;padding:28px 16px\"><section style=\"background:white;border:1px solid #d7e1ef;border-radius:16px;padding:32px\"><p style=\"color:#1769df;font-weight:bold\">한국문화예술교육진흥원 개인정보 동의 안내</p><h1>"+escape(title)+"</h1><p>"+escape(recipientName)+"님, 아래 내용을 확인해 주세요.</p>"+text(n,"introductionHtml")+"<p><strong>처리업무:</strong> "+escape(text(n,"processingActivityName"))+"</p><p><strong>처리 목적:</strong> "+escape(text(n,"processingPurpose"))+"</p><p><strong>보유기간:</strong> "+escape(text(n,"retentionDisplayText"))+"</p>"+items+"<p style=\"margin:28px 0\"><a href=\""+escape(publicUrl)+"\" style=\"background:#1769df;color:white;text-decoration:none;padding:14px 22px;border-radius:9px;font-weight:bold\">기관 웹페이지에서 동의 진행</a></p><p>이메일 본문에서는 동의·미동의를 제출할 수 없습니다.</p><p>링크 만료: "+escape(text(n,"expiresAt"))+"</p><p>"+escape(text(n,"withdrawalNotice"))+"</p></section></main></body></html>";
  return new RenderedConsentMail("[ARTE 개인정보 동의] "+title,html,sha(html));}catch(Exception e){throw new IllegalStateException("동의 안내 메일을 렌더링할 수 없습니다.",e);}}
 private static String text(JsonNode n,String f){return n.path(f).asText("");}private static String escape(String v){return HtmlUtils.htmlEscape(v,StandardCharsets.UTF_8.name());}
 private static String sha(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
